    it.todo("each contract after the first gets the 15 % follow-up discount -> three sword quotes cost 115 G, 100 G, 100 G (100 + 10 - 15 + 5)");
    it.todo("long-standing customer's second contract: 3 years, cursed sword (steel, enchantment 7) -> premium 160 G (100 + 50 + 30 - 20 + 10 - 15 + 5); first insurance still applies");
    it.todo("rounding is always up, not to nearest: second contract for 2 runes + 1 moonstone -> 76.25 G -> premium 77 G");
    it.todo("intermediate amounts stay fractional: second contract for 1 rune -> 25 + 2.5 - 3.75 + 5 = 28.75 G -> premium 29 G");
  });

  describe("claim: standard reimbursement and insurance values", () => {
    it.todo("regular sword (steel, enchantment 3), damage 500 G -> payout 400 G (minus 100 G deductible), remaining cap 1600 G (cap 2 x 1000)");
    it.todo("rune, damage 200 G -> payout 100 G, remaining cap 400 G (insurance value 250 G, cap 500 G)");
    it.todo("amulet, damage 200 G -> payout 100 G, remaining cap 1100 G (insurance value 600 G, cap 1200 G)");
    it.todo("staff, damage 200 G -> payout 100 G, remaining cap 1500 G (insurance value 800 G, cap 1600 G)");
    it.todo("potion, damage 200 G -> payout 100 G, remaining cap 700 G (insurance value 400 G, cap 800 G)");
    it.todo("moonstone, damage 200 G -> payout 100 G, remaining cap 400 G (insurance value 250 G, cap 500 G)");
    it.todo("dragon attack damages sword (500 G) and amulet (300 G) -> payout 600 G (deductible once per damaged item), remaining cap 2600 G (insurance sum 1600 G, cap 3200 G)");
    it.todo("two swords, both damaged by 500 G -> each entry has its own deductible -> payout 800 G, remaining cap 3200 G (insurance sum 2000 G, cap 4000 G)");
    it.todo("cursed sword -> cap 2000 G (premium modifiers do not raise the cap): damage 500 G -> payout 400 G, remaining cap 1600 G");
    it.todo("sword + 3 runes (a block) -> insurance sum 1750 G, cap 3500 G: sword damage 500 G -> payout 400 G, remaining cap 3100 G");
    it.todo("damage below the deductible (sword, 50 G) -> payout 0 G, remaining cap 2000 G (reading: a deductible cannot make a payout negative)");
  });

  describe("claim: special clauses", () => {
    it.todo("steel sword, enchantment 9, damage 1000 G -> payout 400 G (50 % first, then deductible: 500 - 100)");
    it.todo("dragon-material sword with exactly enchantment 8, damage 1000 G -> payout 400 G (high-enchantment clause applies, then deductible)");
