export interface Item {
  type: string;
}

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
const PROCESSING_FEE = 5;
const ONE_HUNDRED_PERCENT = 100;

function policyBasePremium(items: Item[]): number {
  return items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
}

export function quotePremium(items: Item[]): number {
  const basePremium = policyBasePremium(items);
  const firstInsuranceSurcharge = (basePremium * FIRST_INSURANCE_SURCHARGE_PERCENT) / ONE_HUNDRED_PERCENT;
  return basePremium + firstInsuranceSurcharge + PROCESSING_FEE;
}

