import { describe, expect, it } from "vitest";
import { processScenario } from "./claim-office.js";
import type { Item } from "./premium.js";

const newcomer = { yearsWithMHPCO: 0 };

function several(count: number, type: string): Item[] {
  return Array.from({ length: count }, () => ({ type }));
}

function quoteResults(items: Item[]) {
  return processScenario({ customer: newcomer, steps: [{ op: "quote", items }] }).results;
}

describe("MHPCO claim office", () => {
  describe("quote: price list (newcomer's first quote: base premium + 10 % first insurance + 5 G fee)", () => {
    it("empty item list -> premium 5 G (only the processing fee)", () => {
      expect(quoteResults([])).toEqual([{ premium: 5 }]);
    });

    it("sword -> base premium 100 G -> premium 115 G (100 + 10 + 5)", () => {
      expect(quoteResults([{ type: "sword" }])).toEqual([{ premium: 115 }]);
    });

    it("amulet -> base premium 60 G -> premium 71 G (60 + 6 + 5)", () => {
      expect(quoteResults([{ type: "amulet" }])).toEqual([{ premium: 71 }]);
    });

    it("staff -> base premium 80 G -> premium 93 G (80 + 8 + 5)", () => {
      expect(quoteResults([{ type: "staff" }])).toEqual([{ premium: 93 }]);
    });

    it("potion -> base premium 40 G -> premium 49 G (40 + 4 + 5)", () => {
      expect(quoteResults([{ type: "potion" }])).toEqual([{ premium: 49 }]);
    });

    it("sword and amulet -> policy base premium 160 G -> premium 181 G (160 + 16 + 5)", () => {
      expect(quoteResults([{ type: "sword" }, { type: "amulet" }])).toEqual([{ premium: 181 }]);
    });

    it("2 runes -> base premium 50 G -> premium 60 G (50 + 5 + 5)", () => {
      expect(quoteResults(several(2, "rune"))).toEqual([{ premium: 60 }]);
    });

    it("2 moonstones -> base premium 50 G -> premium 60 G (50 + 5 + 5)", () => {
      expect(quoteResults(several(2, "moonstone"))).toEqual([{ premium: 60 }]);
    });

    it("7 runes -> base premium 175 G -> 197.5 G -> final premium 198 G (rounded up)", () => {
      expect(quoteResults(several(7, "rune"))).toEqual([{ premium: 198 }]);
    });

    it("3 runes -> base premium 60 G (block applies) -> premium 71 G (60 + 6 + 5)", () => {
      expect(quoteResults(several(3, "rune"))).toEqual([{ premium: 71 }]);
    });

    it.todo("4 runes -> base premium 100 G (no block: requires exactly 3) -> premium 115 G");
    it.todo("2 runes + 1 moonstone -> base premium 75 G (no block: different types) -> 87.5 G -> premium 88 G");
    it.todo("3 runes + 3 moonstones -> base premium 120 G (two separate blocks) -> premium 137 G (120 + 12 + 5)");
    it.todo("unknown item type broomstick -> throws an Error naming the type (reading: rejection is a thrown Error describing the offending input)");
  });

  describe("quote: item-specific risk surcharges", () => {
    it.todo("newcomer with a cursed sword (steel, enchantment 3) -> premium 165 G (100 + 50 curse + 10 + 5)");
    it.todo("cursed sword + plain amulet -> curse adds 50 G (50 % of the sword only) -> 210 G -> premium 231 G (+ 16 + 5)");
    it.todo("sword with exactly enchantment 5 -> high-enchantment surcharge applies -> premium 145 G (100 + 30 + 10 + 5)");
    it.todo("sword with enchantment 4 -> no high-enchantment surcharge -> premium 115 G");
    it.todo("plain sword + amulet with enchantment 6 -> surcharge 18 G (30 % of the amulet only) -> premium 199 G (160 + 18 + 16 + 5)");
    it.todo("cursed sword with exactly enchantment 5 -> both surcharges apply -> premium 195 G (100 + 50 + 30 + 10 + 5)");
    it.todo("cursed sword with enchantment 4 -> only the curse surcharge applies -> premium 165 G");
  });

  describe("quote: policy-wide modifiers", () => {
    it.todo("customer with exactly 2 years with MHPCO -> loyalty discount applies -> sword premium 95 G (100 - 20 + 10 + 5)");
    it.todo("customer with 1 year with MHPCO -> no loyalty discount -> sword premium 115 G");
    it.todo("loyal customer, cursed sword + plain amulet -> loyalty is 20 % of the policy base premium 160 G, not of surcharges -> premium 199 G (160 + 50 - 32 + 16 + 5)");
    it.todo("each contract after the first gets the 15 % follow-up discount -> three sword quotes cost 115 G, 100 G, 100 G (100 + 10 - 15 + 5)");
    it.todo("long-standing customer's second contract: 3 years, cursed sword (steel, enchantment 7) -> premium 160 G (100 + 50 + 30 - 20 + 10 - 15 + 5); first insurance still applies");
    it.todo("rounding is always up, not to nearest: second contract for 2 runes + 1 moonstone -> 76.25 G -> premium 77 G");
    it.todo("intermediate amounts stay fractional: second contract for 1 rune -> 25 + 2.5 - 3.75 + 5 = 28.75 G -> premium 29 G");
  });

  describe("claim: standard reimbursement and insurance values", () => {
    it.todo("regular sword (steel, enchantment 3), damage 500 G -> payout 400 G (minus 100 G deductible), remaining cap 1600 G (cap 2 x 1000)");
    it.todo("rune, damage 200 G -> payout 100 G, remaining cap 400 G (insurance value 250 G, cap 500 G)");
    it.todo("amulet, damage 200 G -> payout 100 G, remaining cap 1100 G (insurance value 600 G, cap 1200 G)");
    it.todo("staff, damage 200 G -> payout 100 G, remaining cap 1500 G (insurance value 800 G, cap 1600 G)");
    it.todo("potion, damage 200 G -> payout 100 G, remaining cap 700 G (insurance value 400 G, cap 800 G)");
    it.todo("moonstone, damage 200 G -> payout 100 G, remaining cap 400 G (insurance value 250 G, cap 500 G)");
    it.todo("dragon attack damages sword (500 G) and amulet (300 G) -> payout 600 G (deductible once per damaged item), remaining cap 2600 G (insurance sum 1600 G, cap 3200 G)");
    it.todo("two swords, both damaged by 500 G -> each entry has its own deductible -> payout 800 G, remaining cap 3200 G (insurance sum 2000 G, cap 4000 G)");
    it.todo("cursed sword -> cap 2000 G (premium modifiers do not raise the cap): damage 500 G -> payout 400 G, remaining cap 1600 G");
    it.todo("sword + 3 runes (a block) -> insurance sum 1750 G, cap 3500 G: sword damage 500 G -> payout 400 G, remaining cap 3100 G");
    it.todo("damage below the deductible (sword, 50 G) -> payout 0 G, remaining cap 2000 G (reading: a deductible cannot make a payout negative)");
  });

  describe("claim: special clauses", () => {
    it.todo("steel sword, enchantment 9, damage 1000 G -> payout 400 G (50 % first, then deductible: 500 - 100)");
    it.todo("dragon-material sword with exactly enchantment 8, damage 1000 G -> payout 400 G (high-enchantment clause applies, then deductible)");
    it.todo("steel sword, enchantment 7, damage 1000 G -> payout 900 G (below the enchantment 8 threshold: full reimbursement minus deductible)");
    it.todo("dragon-material sword, enchantment 9, damage 1000 G -> payout 400 G (both clauses apply; the 50 % rule wins)");
    it.todo("dragon-material sword, enchantment 5, damage 800 G -> payout 700 G (full reimbursement, then deductible)");
    it.todo("payout calculation that yields 350.5 G (enchantment 9, damage 901 G) -> final payout 350 G (rounded down)");
    it.todo("intermediate payout amounts stay fractional: two enchantment-9 swords damaged by 901 G each -> 350.5 + 350.5 -> payout 701 G");
    it.todo("two swords of different enchantment (9 then 3), damages 1000 G then 500 G -> payout 800 G (reading: damage entries are matched to the policy's items of that type in policy order)");
  });

  describe("claim: cap exhaustion", () => {
    it.todo("sword (cap 2000 G), two successive claims of 1500 G -> payout 1400 G, remaining cap 600 G; then payout 600 G, remaining cap 0 G");
  });

  describe("claim: rejections (reading: a thrown Error describing the offending input)", () => {
    it.todo("damage to an amulet when only a sword is insured -> throws an Error naming the amulet");
    it.todo("damage to an item with an unknown type (broomstick) -> throws an Error naming the type");
    it.todo("two sword damages but only one sword insured -> throws an Error naming the sword; the whole claim is rejected");
    it.todo("damage entry with amount -200 -> throws an Error naming the amount");
  });
});

