import { type Item, policyBasePremium } from "./price-list.js";

const CURSE_SURCHARGE_PERCENT = 50;
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
const PROCESSING_FEE = 5;
const ONE_HUNDRED_PERCENT = 100;

function percentOf(amount: number, percent: number): number {
  return (amount * percent) / ONE_HUNDRED_PERCENT;
}

function roundedUpInFavorOfMHPCO(premium: number): number {
  return Math.ceil(premium);
}

export function quotePremium(items: Item[]): number {
  const basePremium = policyBasePremium(items);
  const curseSurcharge = items
    .filter((item) => item.cursed)
    .reduce((sum, item) => sum + percentOf(itemBasePremium(item), CURSE_SURCHARGE_PERCENT), 0);
  const firstInsuranceSurcharge = percentOf(basePremium, FIRST_INSURANCE_SURCHARGE_PERCENT);
  return roundedUpInFavorOfMHPCO(basePremium + curseSurcharge + firstInsuranceSurcharge + PROCESSING_FEE);
}

export interface Item {
  type: string;
  cursed?: boolean;
}

const MAIN_ITEM_BASE_PREMIUMS = new Map(
  Object.entries({
    sword: 100,
    amulet: 60,
    staff: 80,
    potion: 40,
  }),
);
const COMPONENT_TYPES = ["rune", "moonstone"];
const COMPONENT_BASE_PREMIUM = 25;
const BUILDING_BLOCK_SIZE = 3;
const BUILDING_BLOCK_BASE_PREMIUM = 60;
const BUILDING_BLOCK_SAVING = BUILDING_BLOCK_SIZE * COMPONENT_BASE_PREMIUM - BUILDING_BLOCK_BASE_PREMIUM;

function itemBasePremium(item: Item): number {
  if (COMPONENT_TYPES.includes(item.type)) {
    return COMPONENT_BASE_PREMIUM;
  }
  const mainItemBasePremium = MAIN_ITEM_BASE_PREMIUMS.get(item.type);
  if (mainItemBasePremium === undefined) {
    throw new Error(`Unknown item type: ${item.type}`);
  }
  return mainItemBasePremium;
}

function formsBuildingBlock(items: Item[], componentType: string): boolean {
  return items.filter((item) => item.type === componentType).length === BUILDING_BLOCK_SIZE;
}

export function policyBasePremium(items: Item[]): number {
  const listPremium = items.reduce((sum, item) => sum + itemBasePremium(item), 0);
  const buildingBlocks = COMPONENT_TYPES.filter((componentType) => formsBuildingBlock(items, componentType));
  return listPremium - buildingBlocks.length * BUILDING_BLOCK_SAVING;
}

