export interface Item {
  type: string;
  cursed?: boolean;
}

const MAIN_ITEM_BASE_PREMIUMS = new Map(
  Object.entries({
    sword: 100,
    amulet: 60,
    staff: 80,
    potion: 40,
  }),
);
const COMPONENT_TYPES = ["rune", "moonstone"];
const COMPONENT_BASE_PREMIUM = 25;
const BUILDING_BLOCK_SIZE = 3;
const BUILDING_BLOCK_BASE_PREMIUM = 60;
const BUILDING_BLOCK_SAVING = BUILDING_BLOCK_SIZE * COMPONENT_BASE_PREMIUM - BUILDING_BLOCK_BASE_PREMIUM;

export function itemBasePremium(item: Item): number {
  if (COMPONENT_TYPES.includes(item.type)) {
    return COMPONENT_BASE_PREMIUM;
  }
  const mainItemBasePremium = MAIN_ITEM_BASE_PREMIUMS.get(item.type);
  if (mainItemBasePremium === undefined) {
    throw new Error(`Unknown item type: ${item.type}`);
  }
  return mainItemBasePremium;
}

function formsBuildingBlock(items: Item[], componentType: string): boolean {
