import { type Item, itemBasePremium, policyBasePremium } from "./price-list.js";

const CURSE_SURCHARGE_PERCENT = 50;
const HIGH_ENCHANTMENT_LEVEL = 5;
const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
const PROCESSING_FEE = 5;
const ONE_HUNDRED_PERCENT = 100;

function percentOf(amount: number, percent: number): number {
  return (amount * percent) / ONE_HUNDRED_PERCENT;
}

function roundedUpInFavorOfMHPCO(premium: number): number {
  return Math.ceil(premium);
}

function isHighlyEnchanted(item: Item): boolean {
  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
}

function riskSurchargePercent(item: Item): number {
  const cursePercent = item.cursed ? CURSE_SURCHARGE_PERCENT : 0;
  const highEnchantmentPercent = isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE_PERCENT : 0;
  return cursePercent + highEnchantmentPercent;
}

function itemRiskSurcharge(item: Item): number {
  return percentOf(itemBasePremium(item), riskSurchargePercent(item));
}

export function quotePremium(items: Item[]): number {
  const basePremium = policyBasePremium(items);
  const riskSurcharges = items.reduce((sum, item) => sum + itemRiskSurcharge(item), 0);
  const firstInsuranceSurcharge = percentOf(basePremium, FIRST_INSURANCE_SURCHARGE_PERCENT);
  return roundedUpInFavorOfMHPCO(basePremium + riskSurcharges + firstInsuranceSurcharge + PROCESSING_FEE);
}
import { quotePremium } from "./premium.js";
import type { Item } from "./price-list.js";

export interface Customer {
  yearsWithMHPCO: number;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Scenario {
  customer: Customer;
  steps: QuoteStep[];
}

export interface QuoteResult {
  premium: number;
}

export interface ScenarioResults {
  results: QuoteResult[];
}

export function processScenario(scenario: Scenario): ScenarioResults {
  return { results: scenario.steps.map((step) => ({ premium: quotePremium(step.items) })) };
}

