    it.todo("payout calculation that yields 350.5 G (enchantment 9, damage 901 G) -> final payout 350 G (rounded down)");
    it.todo("intermediate payout amounts stay fractional: two enchantment-9 swords damaged by 901 G each -> 350.5 + 350.5 -> payout 701 G");
    it.todo("two swords of different enchantment (9 then 3), damages 1000 G then 500 G -> payout 800 G (reading: damage entries are matched to the policy's items of that type in policy order)");
  });

  describe("claim: cap exhaustion", () => {
    it.todo("sword (cap 2000 G), two successive claims of 1500 G -> payout 1400 G, remaining cap 600 G; then payout 600 G, remaining cap 0 G");
  });

  describe("claim: rejections (reading: a thrown Error describing the offending input)", () => {
