import { type Damage, claimPayout } from "./claim.js";
import { type Customer, quotePremium } from "./premium.js";
import { type Item, insuranceSum } from "./price-list.js";

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: { cause: string; damages: Damage[] };
}

export interface Scenario {
  customer: Customer;
  steps: (QuoteStep | ClaimStep)[];
}

export interface QuoteResult {
  premium: number;
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

export interface ScenarioResults {
  results: (QuoteResult | ClaimResult)[];
}

const CAP_PER_INSURANCE_SUM = 2;

export function processScenario(scenario: Scenario): ScenarioResults {
  return {
    results: scenario.steps.map((step, previousContracts) => {
      if (step.op === "claim") {
        const policy = scenario.steps[step.policy] as QuoteStep;
        const payout = claimPayout(step.incident.damages);
        return { payout, remainingCap: CAP_PER_INSURANCE_SUM * insuranceSum(policy.items) - payout };
      }
      return { premium: quotePremium(step.items, scenario.customer, previousContracts) };
    }),
  };
}

