import { type Item, insuranceSum } from "./price-list.js";

export interface Damage {
  itemType: string;
  amount: number;
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

const DEDUCTIBLE = 100;
const CAP_PER_INSURANCE_SUM = 2;

function payoutCap(insuredItems: Item[]): number {
  return CAP_PER_INSURANCE_SUM * insuranceSum(insuredItems);
}

export function settleClaim(insuredItems: Item[], damages: Damage[]): ClaimResult {
  const damageTotal = damages.reduce((sum, damage) => sum + damage.amount, 0);
  const payout = damageTotal - DEDUCTIBLE;
  return { payout, remainingCap: payoutCap(insuredItems) - payout };
}

