const DEDUCTIBLE = 100;
const CAP_PER_INSURANCE_SUM = 2;
const REDUCED_REIMBURSEMENT_ENCHANTMENT = 8;
const REDUCED_REIMBURSEMENT_PERCENT = 50;
const ONE_HUNDRED_PERCENT = 100;

function payoutCap(insuredItems: Item[]): number {
  return CAP_PER_INSURANCE_SUM * insuranceSum(insuredItems);
}

function damagePayout(damage: Damage, insuredItems: Item[]): number {
  const damagedItem = insuredItems.find((item) => item.type === damage.itemType);
  const reimbursement =
    (damagedItem?.enchantment ?? 0) >= REDUCED_REIMBURSEMENT_ENCHANTMENT
      ? (damage.amount * REDUCED_REIMBURSEMENT_PERCENT) / ONE_HUNDRED_PERCENT
      : damage.amount;
  return Math.max(reimbursement - DEDUCTIBLE, 0);
}

export function settleClaim(insuredItems: Item[], damages: Damage[]): ClaimResult {
  const payout = damages.reduce((sum, damage) => sum + damagePayout(damage, insuredItems), 0);
  return { payout, remainingCap: payoutCap(insuredItems) - payout };
}

