=== src/price-list.ts
export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

interface PriceListEntry {
  insuranceValue: number;
  basePremium: number;
}

const MAIN_ITEMS = new Map<string, PriceListEntry>(
  Object.entries({
    sword: { insuranceValue: 1000, basePremium: 100 },
    amulet: { insuranceValue: 600, basePremium: 60 },
    staff: { insuranceValue: 800, basePremium: 80 },
    potion: { insuranceValue: 400, basePremium: 40 },
  }),
);
const COMPONENT_TYPES = ["rune", "moonstone"];
const COMPONENT: PriceListEntry = { insuranceValue: 250, basePremium: 25 };
const BUILDING_BLOCK_SIZE = 3;
const BUILDING_BLOCK_BASE_PREMIUM = 60;
const BUILDING_BLOCK_SAVING = BUILDING_BLOCK_SIZE * COMPONENT.basePremium - BUILDING_BLOCK_BASE_PREMIUM;

function priceListEntry(item: Item): PriceListEntry {
  if (COMPONENT_TYPES.includes(item.type)) {
    return COMPONENT;
  }
  const mainItem = MAIN_ITEMS.get(item.type);
  if (mainItem === undefined) {
    throw new Error(`Unknown item type: ${item.type}`);
  }
  return mainItem;
}

export function itemBasePremium(item: Item): number {
  return priceListEntry(item).basePremium;
}

function formsBuildingBlock(items: Item[], componentType: string): boolean {
  return items.filter((item) => item.type === componentType).length === BUILDING_BLOCK_SIZE;
}

export function policyBasePremium(items: Item[]): number {
  const listPremium = items.reduce((sum, item) => sum + itemBasePremium(item), 0);
  const buildingBlocks = COMPONENT_TYPES.filter((componentType) => formsBuildingBlock(items, componentType));
  return listPremium - buildingBlocks.length * BUILDING_BLOCK_SAVING;
}

export function insuranceSum(items: Item[]): number {
  return items.reduce((sum, item) => sum + priceListEntry(item).insuranceValue, 0);
}
=== src/premium.ts
import { percentOf } from "./percent.js";
import { type Item, itemBasePremium, policyBasePremium } from "./price-list.js";
import { premiumRoundedInFavorOfMHPCO } from "./rounding.js";

export interface Customer {
  yearsWithMHPCO: number;
}

const CURSE_SURCHARGE_PERCENT = 50;
const HIGH_ENCHANTMENT_LEVEL = 5;
const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
const LONG_STANDING_YEARS = 2;
const LOYALTY_DISCOUNT_PERCENT = 20;
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
const FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT = 15;
const PROCESSING_FEE = 5;

function isHighlyEnchanted(item: Item): boolean {
  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
}

function riskSurchargePercent(item: Item): number {
  const cursePercent = item.cursed ? CURSE_SURCHARGE_PERCENT : 0;
  const highEnchantmentPercent = isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE_PERCENT : 0;
  return cursePercent + highEnchantmentPercent;
}

function itemRiskSurcharge(item: Item): number {
  return percentOf(itemBasePremium(item), riskSurchargePercent(item));
}

function isLongStandingCustomer(customer: Customer): boolean {
  return customer.yearsWithMHPCO >= LONG_STANDING_YEARS;
}

function isFollowUpContract(previousContracts: number): boolean {
  return previousContracts > 0;
}

function policyWideModifierPercent(customer: Customer, previousContracts: number): number {
